# Code generated by Claude
"""Records a live run so that it can be replayed exactly.

src/replay.py renders the recorded cameras offline and verifies the recorded states.

What is recorded is what the physics received, not what the sources decided, so a keyboard, teleop, policy or scripted run all
replay the same way. Per control tick (150 hertz (Hz) by default, the loop's cfg["source_hz"]) the recorder stores, all as exact
64-bit floating-point numbers (float64):
  * the full ctrl vector (MuJoCo's actuator command vector) written before each of the tick's physics steps (shape [steps, nu]: with
    interpolated arm targets the ctrl changes inside a tick);
  * the world-frame base velocity (vx, vy, wz) written before each of the tick's physics steps;
  * the force limit of each gripper (newtons per finger, written into the finger actuators' force range before the tick's steps).
Verification data: the integration state right after the settle, a hash of the state after every tick, and a full state checkpoint
every `checkpoint_every` ticks (to say what differs when a hash does not match).

    run_dir/
        meta.json              recipe to rebuild the model, loop config, camera specs, rates, spawn, git commit, MuJoCo version, labels
        initial_state.npy      the state after the settle (the replay compares its own settle against it)
        chunks/chunk_00000.npz ... ticks [start, start + n): start, ctrl[n, steps, nu], basevel[n, 3], gripforce[n, 2] (not a number
                               where no force limit was given), hashes[n] (unsigned 64-bit integers), checkpoint ticks and states

Here "meta.json" is a JavaScript Object Notation (JSON) file, and the ".npy" / ".npz" files are NumPy array files (one array, and
an uncompressed bundle of named arrays). Chunks are written every `chunk_ticks` ticks while the run goes, so a crash loses at most the last
chunk. About 150 kilobytes (KB) per simulated second (the ctrl of every physics step is stored).
"""

import hashlib
import json
import platform
import subprocess
import time
from pathlib import Path

import mujoco
import numpy as np

from src import robot_specs

PROJECT_ROOT = Path(__file__).resolve().parent.parent

# State vector compared by the replay: time, positions, velocities, actuator activations, the solver warm start and ctrl.
STATE_SPEC = (mujoco.mjtState.mjSTATE_TIME | mujoco.mjtState.mjSTATE_QPOS | mujoco.mjtState.mjSTATE_QVEL
              | mujoco.mjtState.mjSTATE_ACT | mujoco.mjtState.mjSTATE_WARMSTART | mujoco.mjtState.mjSTATE_CTRL)


def state_layout(model):
    """Lists the pieces of the state vector that STATE_SPEC selects, in order.

    Args:
        model (mujoco.MjModel): The compiled model whose dimensions give the sizes.

    Returns:
        list[tuple[str, int]]: One (name, size) pair per piece, in the order they appear in the vector: "time" (1), "qpos"
        (model.nq), "qvel" (model.nv), "act" (model.na), "qacc_warmstart" (model.nv) and "ctrl" (model.nu).
    """
    return [("time", 1), ("qpos", model.nq), ("qvel", model.nv), ("act", model.na), ("qacc_warmstart", model.nv), ("ctrl", model.nu)]


def new_state_buffer(model):
    """Allocates a zero-filled buffer that can hold one state vector.

    Args:
        model (mujoco.MjModel): The compiled model whose state size is used.

    Returns:
        numpy.ndarray: A float64 array of length mujoco.mj_stateSize(model, STATE_SPEC).
    """
    return np.zeros(mujoco.mj_stateSize(model, STATE_SPEC))


def get_state(model, data, buf):
    """Copies the current simulation state into a buffer.

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): The simulation data to read.
        buf (numpy.ndarray): The buffer from new_state_buffer(); overwritten in place.

    Returns:
        numpy.ndarray: `buf` itself, filled with the state described by STATE_SPEC.
    """
    mujoco.mj_getState(model, data, buf, STATE_SPEC)
    return buf


def state_hash(buf):
    """Hashes a state vector to a 64-bit integer.

    Args:
        buf (numpy.ndarray): A state vector, as filled by get_state().

    Returns:
        int: The 8-byte BLAKE2b digest of the raw bytes of `buf`, read as a little-endian unsigned integer.
    """
    return int.from_bytes(hashlib.blake2b(buf.tobytes(), digest_size=8).digest(), "little")


def describe_state_diff(model, a, b):
    """Describes which pieces of two state vectors differ, and by how much.

    Args:
        model (mujoco.MjModel): The compiled model, which gives the layout of the vectors (see state_layout()).
        a (numpy.ndarray): The first state vector.
        b (numpy.ndarray): The second state vector, of the same length.

    Returns:
        list[str]: One line per differing piece, "name: max |diff| value (index i)", where the index is within the piece.
        ["identical"] if no piece differs.
    """
    out, i = [], 0
    for name, n in state_layout(model):
        d = np.abs(a[i:i + n] - b[i:i + n])
        if n and d.max() > 0:
            out.append(f"{name}: max |diff| {d.max():.3e} (index {int(d.argmax())})")
        i += n
    return out or ["identical"]


def model_hash(model):
    """Hashes the compiled model's arrays, counts and solver options, so a different scene, camera set or edit shows.

    The display settings (model.vis: field of view (FOV), shadow size and so on) are left out: the Graphics Library Framework
    (GLFW) viewer changes those after loading, and they do not affect the physics. model.stat is left out too.

    Args:
        model (mujoco.MjModel): The compiled model.

    Returns:
        str: The hexadecimal Secure Hash Algorithm 256-bit (SHA-256) digest over the names and values of every array and
        count attribute of `model`, and every non-callable attribute of model.opt.
    """
    h = hashlib.sha256()

    def add(name, v):
        h.update(name.encode())
        h.update(np.ascontiguousarray(v).tobytes() if isinstance(v, np.ndarray) else repr(v).encode())
    for name in sorted(dir(model)):
        if name.startswith("_") or name in ("vis", "opt", "stat"):
            continue
        v = getattr(model, name)
        if isinstance(v, np.ndarray) or (name.startswith("n") and isinstance(v, int)):
            add(name, v)
    for name in sorted(dir(model.opt)):
        if not name.startswith("_") and not callable(getattr(model.opt, name)):
            add("opt." + name, getattr(model.opt, name))
    return h.hexdigest()


def jsonable(obj):
    """Converts an object into something the json module can write.

    Args:
        obj (object): A value, or a dict / list / tuple / set of values, possibly nested. NumPy arrays and NumPy scalars are
            accepted.

    Returns:
        object: A copy made of dict (keys turned into str), list, bool, int, float, str and None. Callables inside dicts,
        lists, tuples and sets are dropped; tuples and sets become lists; NumPy arrays become lists; NumPy scalars become
        Python scalars; anything else becomes str(obj).
    """
    if isinstance(obj, dict):
        return {str(k): jsonable(v) for k, v in obj.items() if not callable(v)}
    if isinstance(obj, (list, tuple, set)):
        return [jsonable(v) for v in obj if not callable(v)]
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, (np.floating, np.integer, np.bool_)):
        return obj.item()
    if obj is None or isinstance(obj, (bool, int, float, str)):
        return obj
    return str(obj)


def specs_snapshot():
    """Collects the robot_specs values that a replay needs or should notice a change in.

    Returns:
        dict: The JSON-ready (see jsonable()) values of "CAMERA_SPECS", "PEDESTAL_SPECS", "NECK_SPECS", "CAMERA_HZ" (camera
        frame rate in hertz) and "PHYSICS_HZ" (physics step rate in hertz) from src/robot_specs.py.
    """
    return jsonable({"CAMERA_SPECS": robot_specs.CAMERA_SPECS, "PEDESTAL_SPECS": robot_specs.PEDESTAL_SPECS,
                     "NECK_SPECS": robot_specs.NECK_SPECS, "CAMERA_HZ": robot_specs.CAMERA_HZ, "PHYSICS_HZ": robot_specs.PHYSICS_HZ})


def _git_info():
    """Asks git for the state of the code that made the recording.

    Returns:
        dict: "commit" (str): the hash of HEAD, and "dirty" (bool): whether tracked files have uncommitted changes. Both are
        None if git cannot be run.
    """
    try:
        run = lambda *a: subprocess.run(["git", *a], cwd=PROJECT_ROOT, capture_output=True, text=True, timeout=10).stdout.strip()
        return {"commit": run("rev-parse", "HEAD"), "dirty": bool(run("status", "--porcelain", "--untracked-files=no"))}
    except Exception:
        return {"commit": None, "dirty": None}


class RunRecorder:
    """Writes one recording of a run to disk, tick by tick.

    Created by control_loop.run_loop after the settle when cfg["record_run"] is set. The loop calls tick(), label() and
    end_tick() once per control tick and close() when the run ends.

    Attributes:
        dir (pathlib.Path): The run directory.
        model (mujoco.MjModel): The compiled model being recorded.
        data (mujoco.MjData): The simulation data given at construction.
        chunk_ticks (int): Number of ticks after which a chunk file is written.
        checkpoint_every (int): A full state checkpoint is kept for every tick whose number is a multiple of this.
        buf (numpy.ndarray): Scratch buffer for the state vector.
        ctrl (list[numpy.ndarray]): The ctrl blocks (shape [steps, nu], one row per physics step) of the ticks not yet written to a chunk.
        basevel (list[numpy.ndarray]): The (vx, vy, wz) world-frame base velocities of those ticks.
        hashes (list[int]): The state hashes after those ticks.
        gripforce (list[numpy.ndarray]): The (left, right) gripper force limits of those ticks, in newtons per finger.
        ck_ticks (list[int]): The tick numbers of the checkpoints not yet written.
        ck_states (list[numpy.ndarray]): The checkpoint state vectors not yet written.
        start_tick (int): The tick number of the first tick of the chunk being collected.
        n_chunks (int): Number of chunk files written so far.
        n_ticks (int): Number of ticks whose physics has finished (frame + 1 of the latest end_tick()).
        labels (list[dict]): Entries {"tick": int, "label": str}, one each time the label text changes.
        meta (dict): The contents of meta.json, apart from "labels" and "n_ticks", which are added when it is written.
    """

    def __init__(self, run_dir, model, data, loop_cfg, meta_extra, source_hz, steps_per_tick, chunk_ticks=2400, checkpoint_every=150):
        """Creates the run directory, saves the initial state and writes the first meta.json.

        Args:
            run_dir (str or pathlib.Path): Directory to write into; created (with a "chunks" subdirectory) if needed.
            model (mujoco.MjModel): The compiled model.
            data (mujoco.MjData): The simulation data, right after the settle; its state is saved as initial_state.npy.
            loop_cfg (dict): The control loop's configuration, stored in meta.json as "loop_cfg" (via jsonable()).
            meta_extra (dict): Extra entries for meta.json (the loop's cfg["record_meta"]). It must contain "model", the
                recipe to rebuild the model: {"kind": "scene", "scene": path} or {"kind": "task", "task_cfg": {...}}.
            source_hz (float): Control tick rate in hertz.
            steps_per_tick (int): Physics steps per control tick.
            chunk_ticks (int): Ticks per chunk file (16 s at 150 Hz). Defaults to 2400.
            checkpoint_every (int): Keep a full state checkpoint every this many ticks (1 s at 150 Hz). Defaults to 150.

        Raises:
            ValueError: If `meta_extra` has no "model" entry.
        """
        if not (meta_extra or {}).get("model"):
            raise ValueError('recording a run needs cfg["record_meta"]["model"]: the recipe to rebuild the model '
                             '({"kind": "scene", "scene": path} or {"kind": "task", "task_cfg": {...}})')
        self.dir = Path(run_dir)
        (self.dir / "chunks").mkdir(parents=True, exist_ok=True)
        self.model, self.data = model, data
        self.chunk_ticks, self.checkpoint_every = chunk_ticks, checkpoint_every
        self.buf = new_state_buffer(model)
        self.ctrl, self.basevel, self.hashes, self.gripforce = [], [], [], []
        self.ck_ticks, self.ck_states = [], []
        self.start_tick, self.n_chunks, self.n_ticks = 0, 0, 0
        self.labels = []
        np.save(self.dir / "initial_state.npy", get_state(model, data, self.buf).copy())
        self.meta = {
            "format": 2, "complete": False, "started": time.strftime("%Y-%m-%d %H:%M:%S"),
            "model_sha256": model_hash(model), "nq": model.nq, "nv": model.nv, "nu": model.nu,
            "timestep": model.opt.timestep, "steps_per_tick": steps_per_tick, "source_hz": source_hz,
            "loop_cfg": jsonable(loop_cfg), "mujoco": mujoco.__version__, "platform": platform.platform(),
            "machine": platform.machine(), "python": platform.python_version(), "git": _git_info(),
            "checkpoint_every": checkpoint_every, "seed": None, "robot_specs": specs_snapshot(), **jsonable(meta_extra or {}),
        }
        self._write_meta()

    def _write_meta(self):
        """Writes meta.json from self.meta plus the current labels and tick count."""
        (self.dir / "meta.json").write_text(json.dumps({**self.meta, "labels": self.labels, "n_ticks": self.n_ticks}, indent=1))

    def tick(self, frame, ctrl, basevel, gripforce=None):
        """Records the inputs of one tick, before the tick's physics steps.

        Args:
            frame (int): The tick number. Not used; the ticks are stored in call order.
            ctrl (numpy.ndarray): The ctrl vector written before each physics step of this tick, shape (steps_per_tick, model.nu); copied.
            basevel (tuple[float, float, float]): The world-frame base velocity (vx, vy, wz) in metres per second, metres per
                second and radians per second; copied.
            gripforce (list[float] or None): The force limit of the (left, right) gripper in newtons per finger. Defaults to
                None, which is stored as not-a-number for both.
        """
        self.gripforce.append(np.array(gripforce if gripforce is not None else [np.nan, np.nan], dtype=np.float64))
        self.ctrl.append(np.array(ctrl, dtype=np.float64))
        self.basevel.append(np.array(basevel, dtype=np.float64))

    def label(self, frame, text):
        """Records a text label for the replay (the loop passes the status text, which holds the task phase).

        A label is stored only if `text` is not empty and differs from the previous label.

        Args:
            frame (int): The tick number at which the label starts.
            text (str): The label text.
        """
        if text and (not self.labels or self.labels[-1]["label"] != text):
            self.labels.append({"tick": frame, "label": text})

    def end_tick(self, frame, data):
        """Records the state after one tick's physics steps and writes a chunk when enough ticks have collected.

        Appends the state hash, keeps a checkpoint when `frame` is a multiple of `checkpoint_every`, sets n_ticks to frame + 1,
        and calls _flush() once chunk_ticks ticks of inputs have collected.

        Args:
            frame (int): The tick number.
            data (mujoco.MjData): The simulation data after the tick's physics steps.
        """
        get_state(self.model, data, self.buf)
        self.hashes.append(state_hash(self.buf))
        if frame % self.checkpoint_every == 0:
            self.ck_ticks.append(frame)
            self.ck_states.append(self.buf.copy())
        self.n_ticks = frame + 1
        if len(self.ctrl) >= self.chunk_ticks:
            self._flush()

    def _flush(self):
        """Writes the collected ticks to the next chunk file, clears the collected lists and rewrites meta.json.

        Does nothing if no tick has a state hash yet. A tick whose inputs were recorded but whose physics did not finish has no
        hash and is dropped.
        """
        if not self.hashes:
            return
        n = len(self.hashes)                        # a tick whose physics did not finish has inputs but no hash: dropped
        np.savez(self.dir / "chunks" / f"chunk_{self.n_chunks:05d}.npz", start=self.start_tick, ctrl=np.array(self.ctrl[:n]),
                 basevel=np.array(self.basevel[:n]), gripforce=np.array(self.gripforce[:n]), hashes=np.array(self.hashes, dtype=np.uint64), ck_ticks=np.array(self.ck_ticks, dtype=np.int64),
                 ck_states=np.array(self.ck_states).reshape(len(self.ck_states), -1))
        self.start_tick += n
        self.n_chunks += 1
        self.ctrl, self.basevel, self.hashes, self.gripforce, self.ck_ticks, self.ck_states = [], [], [], [], [], []
        self._write_meta()

    def close(self, extra=None):
        """Writes the last chunk, marks the recording complete in meta.json and prints a one-line summary.

        Args:
            extra (dict or None): Entries to add to meta.json (the loop passes "stopped_by" and "frames"). Defaults to None.
        """
        self._flush()
        self.meta.update(complete=True, finished=time.strftime("%Y-%m-%d %H:%M:%S"), **jsonable(extra or {}))
        self._write_meta()
        print(f"Run recorded: {self.dir}  ({self.n_ticks} ticks, {self.n_ticks / self.meta['source_hz']:.1f} s sim time)")


def load_recording(run_dir):
    """Reads a recording written by RunRecorder.

    Prints a warning if the recording was not closed cleanly (meta.json says it is not complete).

    Args:
        run_dir (str or pathlib.Path): The run directory.

    Returns:
        dict: With T the number of recorded ticks and nu the number of actuators:
            "meta" (dict): the contents of meta.json.
            "initial_state" (numpy.ndarray): the state after the settle.
            "ctrl" (numpy.ndarray): shape [T, steps, nu], the ctrl vector of every physics step of every tick (format 1 recordings: [T, nu],
                one vector per tick).
            "basevel" (numpy.ndarray): shape [T, 3], the world-frame base velocity (vx, vy, wz) of every tick.
            "gripforce" (numpy.ndarray or None): shape [T, 2], the (left, right) gripper force limits in newtons per finger;
                None for older recordings made before this was recorded (the force ceiling throughout).
            "hashes" (numpy.ndarray): shape [T], the state hash after every tick, unsigned 64-bit integers.
            "checkpoints" (dict[int, numpy.ndarray]): tick number -> full state vector.

    Raises:
        ValueError: If there are no chunk files or the first chunk does not start at tick 0.
    """
    run_dir = Path(run_dir)
    meta = json.loads((run_dir / "meta.json").read_text())
    files = sorted((run_dir / "chunks").glob("chunk_*.npz"))
    if not files:
        raise ValueError(f"{run_dir}: no recorded ticks")
    parts = [np.load(f) for f in files]
    ctrl = np.concatenate([p["ctrl"] for p in parts])
    basevel = np.concatenate([p["basevel"] for p in parts])
    gripforce = np.concatenate([p["gripforce"] for p in parts]) if all("gripforce" in p.files for p in parts) else None    # older recordings: the ceiling throughout
    hashes = np.concatenate([p["hashes"] for p in parts])
    ck = {int(t): s for p in parts for t, s in zip(p["ck_ticks"], p["ck_states"])}
    if int(parts[0]["start"]) != 0:
        raise ValueError(f"{run_dir}: the first chunk does not start at tick 0")
    if not meta.get("complete"):
        print(f"WARNING: {run_dir} was not closed cleanly (crash?); using the {len(ctrl)} ticks that were written")
    return {"meta": meta, "initial_state": np.load(run_dir / "initial_state.npy"), "ctrl": ctrl, "basevel": basevel, "gripforce": gripforce,
            "hashes": hashes, "checkpoints": ck}
